import{_ as e,o as r,c as a,a0 as s}from"./chunks/framework.l456sJqm.js";const b="/mtbbs/images/index/Pasted%20image%2020260104130930.png",h="/mtbbs/images/index/Pasted%20image%2020260104130844.png",i="/mtbbs/images/index/Pasted%20image%2020260104131138.png",o="/mtbbs/images/index/Pasted%20image%2020260104131438.png",u=JSON.parse('{"title":"mtbbs — MT论坛 移动端适配脚本与工具","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1783219346000}'),d={name:"index.md"};function n(l,t,p,c,m,f){return r(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="mtbbs-—-mt论坛-移动端适配脚本与工具" tabindex="-1">mtbbs — MT论坛 移动端适配脚本与工具 <a class="header-anchor" href="#mtbbs-—-mt论坛-移动端适配脚本与工具" aria-label="Permalink to &quot;mtbbs — MT论坛 移动端适配脚本与工具&quot;">​</a></h1><p>这里是 <a href="https://github.com/qcxs/mtbbs" target="_blank" rel="noreferrer">qcxs/mtbbs</a>，存储了<strong>自用</strong>适配 <a href="https://bbs.binmt.cc/" target="_blank" rel="noreferrer">MT 论坛</a> <strong>移动端</strong>的脚本、网站。</p><p>初始只是个人为 <a href="https://www.alookweb.com/" target="_blank" rel="noreferrer">Alook 浏览器</a> 编写一些脚本，存放在 123 盘中。经历了不断优化，有三种脚本成功入围 <a href="https://bbs.binmt.cc/forum.php?mod=forumdisplay&amp;fid=42&amp;filter=digest&amp;digest=1" target="_blank" rel="noreferrer">编程开发 - MT论坛</a> 精华帖，现将脚本源码统一整理，存储在此仓库中，随缘更新。</p><p>PS：由于Alook佛系更新，转至雨见浏览器，支持插件，随新脚本不只是纯js，开始拥抱油猴API。</p><h2 id="脚本使用方法" tabindex="-1">脚本使用方法 <a class="header-anchor" href="#脚本使用方法" aria-label="Permalink to &quot;脚本使用方法&quot;">​</a></h2><h3 id="通过脚本猫安装-推荐" tabindex="-1">通过脚本猫安装（推荐） <a class="header-anchor" href="#通过脚本猫安装-推荐" aria-label="Permalink to &quot;通过脚本猫安装（推荐）&quot;">​</a></h3><p><a href="https://scriptcat.org/zh-CN/users/202514" target="_blank" rel="noreferrer">qcxs - 用户主页 | ScriptCat</a></p><p>不一定将所有脚本都发布在脚本猫中，但最新脚本在此更新。</p><h3 id="通过-github-安装" tabindex="-1">通过 GitHub 安装 <a class="header-anchor" href="#通过-github-安装" aria-label="Permalink to &quot;通过 GitHub 安装&quot;">​</a></h3><p><strong>核心脚本总在更新，此处不再提供最新代码</strong></p><p>在仓库中找到以 <code>user.js</code> 结尾的文件，它就是脚本。</p><p><img src="'+b+'" alt="在仓库中查找 user.js 文件"></p><p>点击 <strong>Raw</strong>，油猴自动识别。</p><p><img src="'+h+'" alt="点击 Raw 按钮"></p><h3 id="使用-cdn-加速" tabindex="-1">使用 CDN 加速 <a class="header-anchor" href="#使用-cdn-加速" aria-label="Permalink to &quot;使用 CDN 加速&quot;">​</a></h3><p>由于国内访问 GitHub 时好时坏，可以通过 jsDelivr 进行 CDN 加速。</p><p><a href="https://cdn.jsdelivr.net/gh/qcxs/mtbbs/" target="_blank" rel="noreferrer">https://cdn.jsdelivr.net/gh/qcxs/mtbbs/</a></p><p><img src="'+i+'" alt="jsDelivr CDN"></p><p>不过由于缓存，需等待一段时间才能获取到最新版本。</p><h3 id="从-url-安装" tabindex="-1">从 URL 安装 <a class="header-anchor" href="#从-url-安装" aria-label="Permalink to &quot;从 URL 安装&quot;">​</a></h3><p>脚本已重命名为 <code>user.js</code> 后缀，正常情况下，油猴会自动识别安装，也可自行输入 URL 安装。</p><p><img src="'+o+'" alt="从 URL 安装"></p><h2 id="网站" tabindex="-1">网站 <a class="header-anchor" href="#网站" aria-label="Permalink to &quot;网站&quot;">​</a></h2><p>仓库开启了 GitHub Pages，可通过 <a href="https://qcxs.github.io/mtbbs" target="_blank" rel="noreferrer">qcxs.github.io/mtbbs</a> 访问。</p><h3 id="工具" tabindex="-1">工具 <a class="header-anchor" href="#工具" aria-label="Permalink to &quot;工具&quot;">​</a></h3><ul><li><a href="https://qcxs.github.io/mtbbs/mt-convert/" target="_blank" rel="noreferrer">MT Convert 转换器 - Markdown/BBCode/HTML 互转</a></li></ul><h2 id="脚本" tabindex="-1">脚本 <a class="header-anchor" href="#脚本" aria-label="Permalink to &quot;脚本&quot;">​</a></h2><table tabindex="0"><thead><tr><th>脚本</th><th>说明</th><th>帖子</th></tr></thead><tbody><tr><td><a href="/mtbbs/scripts/copy">&quot;借鉴一下&quot;</a></td><td>一键发出几乎和大佬一样的帖子</td><td><a href="https://bbs.binmt.cc/thread-154148-1-1.html" target="_blank" rel="noreferrer">【论坛神器】一键发出几乎和大佬一样的帖子（copy.js）</a></td></tr><tr><td><a href="/mtbbs/scripts/autoNextPage">自动下一页</a></td><td>论坛阅读辅助工具</td><td><a href="https://bbs.binmt.cc/thread-159149-1-1.html" target="_blank" rel="noreferrer">【论坛脚本】论坛阅读辅助工具-自动下一页</a></td></tr><tr><td><a href="/mtbbs/scripts/messagePreview">消息提醒预览</a></td><td>消息预览+回帖查看</td><td><a href="https://bbs.binmt.cc/thread-165883-1-1.html" target="_blank" rel="noreferrer">【油猴脚本】消息预览+回帖查看</a></td></tr><tr><td><a href="/mtbbs/scripts/restoreImages">移动端图片恢复</a></td><td>恢复失效的图片</td><td><a href="https://bbs.binmt.cc/thread-166955-1-1.html" target="_blank" rel="noreferrer">【MT论坛】移动端图片恢复功能</a></td></tr><tr><td><a href="/mtbbs/scripts/InsertLabel">发帖辅助工具</a></td><td>论坛自用发帖工具</td><td><a href="https://bbs.binmt.cc/thread-154052-1-1.html" target="_blank" rel="noreferrer">【论坛脚本】论坛自用发帖工具js（InsertLabel_2.0.js）</a></td></tr><tr><td><a href="/mtbbs/scripts/xhw">手机版小黑屋</a></td><td>手机版小黑屋</td><td><a href="https://bbs.binmt.cc/thread-153883-1-1.html" target="_blank" rel="noreferrer">手机版小黑屋纯js版分享</a></td></tr><tr><td><a href="/mtbbs/scripts/titileTools">标题增强</a></td><td>标题快捷跳转</td><td>-</td></tr></tbody></table><h2 id="核心库" tabindex="-1">核心库 <a class="header-anchor" href="#核心库" aria-label="Permalink to &quot;核心库&quot;">​</a></h2><p><a href="https://github.com/qcxs/mtbbs/tree/main/require/" target="_blank" rel="noreferrer">require/</a> — BBCode/HTML 互转核心库，抽离出供油猴脚本 require 使用的公共代码。</p><h2 id="其它" tabindex="-1">其它 <a class="header-anchor" href="#其它" aria-label="Permalink to &quot;其它&quot;">​</a></h2><p>很有用，推荐阅读。</p><ul><li><a href="https://bbs.binmt.cc/thread-166223-1-1.html" target="_blank" rel="noreferrer">【研究报告】MT论坛bbcode与html互转思路及坑</a></li></ul><p>更多内容，推荐去考古 <a href="https://bbs.binmt.cc/home.php?mod=space&amp;uid=88062&amp;do=profile" target="_blank" rel="noreferrer">个人中心 - MT论坛</a>。</p>',34)])])}const _=e(d,[["render",n]]);export{u as __pageData,_ as default};
